module.exports = /*#__PURE__*/JSON.parse('{"title":"心脏CT","description":"本页面介绍心脏CT的基本原理，包括前瞻性和回顾性门控技术、时间分辨率和辐射剂量考虑。","sections":[{"id":"cardiac-gating","title":"心脏门控技术","description":"心脏CT扫描需要特殊的门控技术来减少心脏运动引起的伪影。","content":"心脏是一个不断运动的器官，这给CT成像带来了挑战。为了获得清晰的心脏图像，需要使用特殊的门控技术来减少心脏运动引起的伪影。有两种主要的门控技术：前瞻性门控和回顾性门控。","simulator":{"type":"cardiac-gating","options":{"gatingTypes":[{"id":"prospective","name":"前瞻性门控"},{"id":"retrospective","name":"回顾性门控"}],"heartRates":[60,70,80,90,100]}},"keyPoints":["前瞻性门控在预测的心动周期特定阶段（通常是舒张中期）获取数据","回顾性门控在整个心动周期连续获取数据，然后在重建时选择最佳相位","前瞻性门控辐射剂量较低，但对心率不规则的患者效果较差","回顾性门控允许评估心脏功能，但辐射剂量较高"]},{"id":"temporal-resolution","title":"时间分辨率","description":"时间分辨率是指CT扫描仪捕获移动物体清晰图像的能力，对心脏成像尤为重要。","content":"时间分辨率是指CT扫描仪捕获移动物体清晰图像的能力。对于心脏成像，高时间分辨率至关重要，因为心脏不断运动。时间分辨率主要取决于旋转时间（X射线管绕患者旋转一周所需的时间）。现代心脏CT扫描仪的旋转时间通常为0.28-0.35秒。然而，通过使用部分扫描重建技术，有效时间分辨率可以提高到旋转时间的一半左右。","keyPoints":["时间分辨率对心脏成像至关重要","旋转时间是决定时间分辨率的主要因素","部分扫描重建可以提高有效时间分辨率","双源CT扫描仪通过使用两个X射线管进一步提高时间分辨率"]},{"id":"radiation-dose","title":"辐射剂量","description":"心脏CT扫描的辐射剂量取决于多种因素，包括门控技术、扫描范围和患者特征。","content":"心脏CT扫描的辐射剂量取决于多种因素，包括门控技术、扫描范围和患者特征。回顾性门控通常比前瞻性门控的辐射剂量高3-4倍，因为它在整个心动周期连续获取数据。然而，现代CT扫描仪使用多种技术来减少辐射剂量，包括ECG调制（在心动周期的特定阶段降低管电流）、迭代重建和低kV成像。","simulator":{"type":"radiation-dose","options":{"gatingTypes":[{"id":"prospective","name":"前瞻性门控"},{"id":"retrospective","name":"回顾性门控"},{"id":"retrospective-modulation","name":"带ECG调制的回顾性门控"}],"patientSizes":[{"id":"small","name":"小型患者"},{"id":"medium","name":"中型患者"},{"id":"large","name":"大型患者"}]}},"keyPoints":["回顾性门控的辐射剂量通常比前瞻性门控高3-4倍","ECG调制可以在心动周期的非关键阶段降低管电流，减少辐射剂量","迭代重建和低kV成像可以进一步减少辐射剂量","患者特征（如体型）也会影响辐射剂量"]},{"id":"clinical-applications","title":"临床应用","description":"心脏CT在多种临床情况下有重要应用，包括冠状动脉疾病评估、结构性心脏病和术前规划。","content":"心脏CT在多种临床情况下有重要应用。最常见的应用是冠状动脉疾病的评估，特别是对于有中等冠心病风险的患者。心脏CT还可用于评估心脏结构（如心脏瓣膜、心房和心室）、先天性心脏病和心脏肿瘤。此外，它在术前规划（如经导管主动脉瓣置换术和冠状动脉旁路移植术）中也发挥着重要作用。","keyPoints":["冠状动脉疾病评估是心脏CT最常见的应用","心脏CT可用于评估心脏结构和先天性心脏病","心脏CT在术前规划中发挥重要作用","心脏CT的高阴性预测值使其成为排除冠状动脉疾病的有效工具"]}]}');

